// Core tests: the 16 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and invariant cases from the
// SPEC's tests section. The extra numeric expectations below were derived
// from the SPEC's formulas with an independent implementation (see
// VERIFICATION.md), not from this product's output.

import assert from "node:assert/strict";
import test from "node:test";
import { formatDelta, formatTemp, run } from "../public/js/core/feels-like.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { temperature: "20", windSpeed: "10", humidity: "50" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("wind speed 4.9 km/h enters wind chill where 4.8 does not", () => {
  assert.deepEqual(run({ temperature: "10", windSpeed: "4.9", humidity: "50" }), {
    ok: true,
    result: { model: "wind-chill", feelsLikeC: 9.8, deltaC: -0.2 },
  });
});

test("temperature 10.1 °C stays actual even in strong wind", () => {
  assert.deepEqual(run({ temperature: "10.1", windSpeed: "20", humidity: "50" }), {
    ok: true,
    result: { model: "actual", feelsLikeC: 10.1, deltaC: 0 },
  });
});

test("legal extremes: -60 °C at 300 km/h wind chill; 60 °C dry stays actual; calm -60 stays actual", () => {
  assert.deepEqual(run({ temperature: "-60", windSpeed: "300", humidity: "50" }), {
    ok: true,
    result: { model: "wind-chill", feelsLikeC: -111.7, deltaC: -51.7 },
  });
  assert.deepEqual(run({ temperature: "60", windSpeed: "0", humidity: "0" }), {
    ok: true,
    result: { model: "actual", feelsLikeC: 60, deltaC: 0 },
  });
  assert.deepEqual(run({ temperature: "-60", windSpeed: "0", humidity: "100" }), {
    ok: true,
    result: { model: "actual", feelsLikeC: -60, deltaC: 0 },
  });
});

test("high-humidity adjustment: RH 85 does not adjust, RH 86 does, RH 100 at 30 °C", () => {
  assert.deepEqual(run({ temperature: "28", windSpeed: "10", humidity: "85" }), {
    ok: true,
    result: { model: "heat-index", feelsLikeC: 32.9, deltaC: 4.9 },
  });
  assert.deepEqual(run({ temperature: "28", windSpeed: "10", humidity: "86" }), {
    ok: true,
    result: { model: "heat-index", feelsLikeC: 33.1, deltaC: 5.1 },
  });
  assert.deepEqual(run({ temperature: "30", windSpeed: "10", humidity: "100" }), {
    ok: true,
    result: { model: "heat-index", feelsLikeC: 44.4, deltaC: 14.4 },
  });
});

test("temperature range: 60.1, -60.1 and -61 are RANGE", () => {
  for (const temperature of ["60.1", "-60.1", "-61"]) {
    assert.deepEqual(errorOf({ ...base, temperature }), {
      code: "RANGE",
      field: "temperature",
      row: null,
    });
  }
});

test("temperature grammar: plus sign, bare fraction, trailing dot, exponent and full-width minus are DECIMAL_FORMAT", () => {
  for (const temperature of ["+5", ".5", "5.", "1e3", "−5", " 5", "5 "]) {
    assert.deepEqual(errorOf({ ...base, temperature }), {
      code: "DECIMAL_FORMAT",
      field: "temperature",
      row: null,
    });
  }
});

test("wind speed: a minus sign is DECIMAL_FORMAT, 300.1 is RANGE, 6 units is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, windSpeed: "-1" }), {
    code: "DECIMAL_FORMAT",
    field: "windSpeed",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, windSpeed: "300.1" }), {
    code: "RANGE",
    field: "windSpeed",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, windSpeed: "123456" }), {
    code: "INPUT_LIMIT",
    field: "windSpeed",
    row: null,
  });
});

test("humidity: 100.1 is RANGE, empty is EMPTY, a lone surrogate is UNICODE", () => {
  assert.deepEqual(errorOf({ ...base, humidity: "100.1" }), {
    code: "RANGE",
    field: "humidity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, humidity: "" }), {
    code: "EMPTY",
    field: "humidity",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, humidity: "\uD800" }), {
    code: "UNICODE",
    field: "humidity",
    row: null,
  });
});

test("raw length is checked before grammar: a 7-unit temperature is INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...base, temperature: "1234567" }), {
    code: "INPUT_LIMIT",
    field: "temperature",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ temperature: "61", windSpeed: "10", humidity: "abc" }), {
    code: "RANGE",
    field: "temperature",
    row: null,
  });
  assert.deepEqual(errorOf({ temperature: "25", windSpeed: "", humidity: "abc" }), {
    code: "EMPTY",
    field: "windSpeed",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.humidity;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, temperature: 20 }), schema);
  assert.deepEqual(errorOf(["20"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("20"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "temperature", {
    enumerable: true,
    get() {
      return "20";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("invariant: every wind-chill result is below the air temperature", () => {
  const inputs = [
    { temperature: "10", windSpeed: "5", humidity: "50" },
    { temperature: "0", windSpeed: "100", humidity: "50" },
    { temperature: "-40", windSpeed: "10", humidity: "50" },
    { temperature: "9.9", windSpeed: "300", humidity: "50" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    assert.equal(outcome.result.model, "wind-chill");
    assert.ok(outcome.result.feelsLikeC < Number(input.temperature));
    assert.ok(outcome.result.deltaC < 0);
  }
});

test("invariant: every actual result reports the temperature itself with deltaC exactly 0", () => {
  const inputs = [
    { temperature: "22", windSpeed: "10", humidity: "60" },
    { temperature: "-5", windSpeed: "4.8", humidity: "50" },
    { temperature: "26.9", windSpeed: "10", humidity: "100" },
    { temperature: "30", windSpeed: "10", humidity: "39.9" },
  ];
  for (const input of inputs) {
    const outcome = run(input);
    assert.equal(outcome.ok, true);
    assert.equal(outcome.result.model, "actual");
    assert.equal(outcome.result.feelsLikeC, Number(input.temperature));
    assert.equal(outcome.result.deltaC, 0);
  }
});

test("display formatting: one decimal always, delta carries an explicit sign", () => {
  assert.equal(formatTemp(-24.2), "-24.2");
  assert.equal(formatTemp(35), "35.0");
  assert.equal(formatTemp(0), "0.0");
  assert.equal(formatTemp(26.9), "26.9");
  assert.equal(formatDelta(5), "+5.0");
  assert.equal(formatDelta(-9.2), "-9.2");
  assert.equal(formatDelta(0), "0.0");
  assert.equal(formatDelta(-0.1), "-0.1");
});
